<?php
require_once __DIR__.'/../app/auth.php'; require_once __DIR__.'/../app/helpers.php';
$q=trim($_POST['q']??'');$topic_id=(int)($_POST['topic_id']??0); if($q===''){header('Location: ../search.php');exit;}
$terms=preg_split('/\s+/u',mb_strtolower($q));$terms=array_values(array_filter($terms,fn($x)=>mb_strlen($x)>=2));$conditions=[];$params=[];foreach(array_slice($terms,0,8) as $term){$like='%'.$term.'%';$conditions[]='(c.title_en LIKE ? OR c.title_ta LIKE ? OR c.body_en LIKE ? OR c.body_ta LIKE ? OR t.title_en LIKE ? OR s.title_en LIKE ?)';array_push($params,$like,$like,$like,$like,$like,$like);} $sql="SELECT c.id,c.title_en,c.title_ta,c.body_en,c.body_ta,c.subtopic_id,t.title_en topic,s.title_en subtopic,t.audience FROM contents c JOIN subtopics s ON s.id=c.subtopic_id JOIN topics t ON t.id=s.topic_id WHERE t.active=1 AND s.active=1 AND (t.audience='public'";if($u=user()){ if(in_array($u['role'],['professional','admin'],true)){$sql.=" OR t.audience='professional'";} } $sql.=')'; if($topic_id){$sql.=' AND t.id=?';$params[]=$topic_id;}if($conditions)$sql.=' AND ('.implode(' OR ',$conditions).')';$sql.=' ORDER BY c.updated_at DESC LIMIT 8';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
$context='';foreach($rows as $r){$context .= "\n[Topic: {$r['topic']} | Subtopic: {$r['subtopic']} | Content ID: {$r['id']}]\n{$r['title_en']}\n{$r['body_en']}\n{$r['body_ta']}\n";}
if(OPENAI_API_KEY && $context){$payload=['model'=>OPENAI_MODEL,'messages'=>[['role'=>'system','content'=>'You are ASK AI inside Siddha Child Care, a pediatric knowledge dissemination website. Answer only from the supplied website content. If the supplied content does not answer the question, say that the website does not currently contain enough information. Do not invent clinical recommendations. This is educational information, not a diagnosis or prescription. Mention the relevant topic/subtopic and content IDs when useful.'],['role'=>'user','content'=>"Question: {$q}\n\nWebsite content:\n{$context}"]],'temperature'=>0.2];$ch=curl_init(OPENAI_BASE_URL.'/chat/completions');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.OPENAI_API_KEY],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>30]);$raw=curl_exec($ch);$err=curl_error($ch);curl_close($ch);$data=json_decode($raw,true);$answer=$data['choices'][0]['message']['content']??null;}else{$answer=$rows?"AI is not configured, so here are the closest matches found in the website\'s stored knowledge.":"No matching information was found in the website\'s stored knowledge.";}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ASK AI – <?=e(APP_NAME)?></title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="topbar"><div class="brand"><div class="logo">SC</div><div><strong>SIDDHA CHILD CARE</strong><small>ASK AI</small></div></div><nav><a href="../index.php">Home</a><a href="../search.php">Search</a></nav></header><main class="container"><div class="card ai-widget"><span class="tag">ASK AI</span><h1><?=e($q)?></h1><div class="ai-answer"><?=nl2br(e($answer ?: 'The AI service did not return an answer.'))?></div><p class="muted">This response is based only on content currently stored in this website. It is not a RAG/vector-database system.</p></div><?php if($rows):?><h2>Knowledge used / matching pages</h2><div class="grid"><?php foreach($rows as $r):?><div class="card"><span class="tag"><?=e($r['topic'])?></span><h3><?=e($r['title_en'])?></h3><p class="muted"><?=e($r['subtopic'])?> · Content #<?=e($r['id'])?></p><p><?=e(excerpt($r['body_en']))?></p><a class="btn secondary" href="../content.php?subtopic=<?=e($r['subtopic_id'])?>#content-<?=e($r['id'])?>">Open source</a></div><?php endforeach;?></div><?php endif;?></main><footer>© <?=date('Y')?> Siddha Child Care</footer></body></html>
